import asyncio
import cognee
from cognee.low_level import DataPoint
from cognee.modules.pipelines import Task
from cognee.tasks.storage import add_data_points

class Person(DataPoint):
    name: str
    metadata: dict = {"index_fields": ["name"], "identity_fields": ["name"]}

class Department(DataPoint):
    name: str
    employees: list[Person]
    metadata: dict = {"index_fields": ["name"], "identity_fields": ["name"]}

class Company(DataPoint):
    name: str
    departments: list[Department]
    metadata: dict = {"index_fields": ["name"], "identity_fields": ["name"]}

def ingest_files(rows):
    return [
        Company(
            name=row["company"],
            departments=[Department(
                name=row["department"],
                employees=[Person(name=row["person"])],
            )],
        )
        for row in rows
    ]

async def main():
    await cognee.run_custom_pipeline(
        tasks=[Task(ingest_files), Task(add_data_points)],
        data=[{"company": "GreenFuture", "department": "R&D", "person": "Alice"}],
        dataset="org",
        pipeline_name="organizational_hierarchy",
    )

asyncio.run(main())

import asyncio
import cognee
from cognee import SearchType

async def main(enable_steps, text_list):
    if enable_steps.get("prune_data"):
        await cognee.prune.prune_data()
    if enable_steps.get("prune_system"):
        await cognee.prune.prune_system(metadata=True)
    if enable_steps.get("add_text"):
        for text in text_list:
            await cognee.add(text)
    if enable_steps.get("cognify"):
        await cognee.cognify()
    if enable_steps.get("retriever"):
        return await cognee.search(
            query_text="Who has experience in design tools?",
            query_type=SearchType.GRAPH_COMPLETION,
        )
    return []

steps = {
    "prune_data": True,
    "prune_system": True,
    "add_text": True,
    "cognify": True,
    "retriever": True,
}
asyncio.run(main(steps, ["Alice: Python, Spark", "David: Photoshop, Illustrator"]))

import asyncio

from claude_agent_sdk import (
    AssistantMessage,
    ClaudeAgentOptions,
    ClaudeSDKClient,
    TextBlock,
    create_sdk_mcp_server,
)
from cognee_integration_claude import cognee_tools


async def main():
    server = create_sdk_mcp_server(
        name="cognee-tools",
        version="1.0.0",
        tools=cognee_tools(),
    )
    options = ClaudeAgentOptions(
        mcp_servers={"tools": server},
        allowed_tools=[
            "mcp__tools__remember",
            "mcp__tools__recall",
        ],
    )

    async with ClaudeSDKClient(options=options) as client:
        await client.query(
            "请先记住:支付服务的重试上限是 3 次;然后回忆重试上限。"
        )
        async for message in client.receive_response():
            if isinstance(message, AssistantMessage):
                for block in message.content:
                    if isinstance(block, TextBlock):
                        print(block.text)


if __name__ == "__main__":
    asyncio.run(main())

